    cin.tie(0);

    int arr[3], N;
    for(int i = 0; i < 3; ++i) cin >> arr[i];
    cin >> N;

    bool answer = false;
    for(int i = 0; arr[0] * i <= N; ++i) {
        for(int j = 0; arr[0] * i + arr[1] * j <= N; ++j) {
            int rem = N - arr[0] * i - arr[1] * j;
            if(rem % arr[2] == 0) answer = true;
        }
    }
    cout << answer;

    return 0;
}

