import sys
input = sys.stdin.readline
n, m, r = map(int, input().split())
arr = [list(map(int, input().split())) for _ in range(n)]
layers = min(n, m) // 2
for layer in range(layers):
    positions = []
    for c in range(layer, m - layer):
        positions.append((layer, c))
    for row in range(layer + 1, n - layer):
        positions.append((row, m - layer - 1))
    for c in range(m - layer - 2, layer - 1, -1):
        positions.append((n - layer - 1, c))
    for row in range(n - layer - 2, layer, -1):
        positions.append((row, layer))
    values = [arr[row][col] for row, col in positions]
    shift = r % len(values)
    for idx, (row, col) in enumerate(positions):
        arr[row][col] = values[(idx + shift) % len(values)]
print('\n'.join(' '.join(map(str, row)) for row in arr))

import itertools, sys
from collections import deque
input = sys.stdin.readline
n, m = map(int, input().split())
board = [list(map(int, input().split())) for _ in range(n)]
viruses = []
empty = 0
for i in range(n):
    for j in range(n):
        if board[i][j] == 2:
            viruses.append((i, j))
        elif board[i][j] == 0:
            empty += 1
if empty == 0:
    print(0)
    sys.exit()
answer = 10 ** 9
dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
for starts in itertools.combinations(viruses, m):
    dist = [[-1] * n for _ in range(n)]
    q = deque()
    for r, c in starts:
        dist[r][c] = 0
        q.append((r, c))
    infected = 0
    last = 0
    while q:
        r, c = q.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and board[nr][nc] != 1 and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                if board[nr][nc] == 0:
                    infected += 1
                    last = dist[nr][nc]
                q.append((nr, nc))
    if infected == empty:
        answer = min(answer, last)
print(-1 if answer == 10 ** 9 else answer)

import sys
input = sys.stdin.readline
n, m, r = map(int, input().split())
arr = [list(map(int, input().split())) for _ in range(n)]
ops = list(map(int, input().split()))

def op1(a):
    return a[::-1]

def op2(a):
    return [row[::-1] for row in a]

def op3(a):
    return [list(row) for row in zip(*a[::-1])]

def op4(a):
    return [list(row) for row in zip(*a)][::-1]

def split(a):
    h, w = len(a) // 2, len(a[0]) // 2
    return [
        [row[:w] for row in a[:h]],
        [row[w:] for row in a[:h]],
        [row[:w] for row in a[h:]],
        [row[w:] for row in a[h:]],
    ]

def merge(parts):
    top = [parts[0][i] + parts[1][i] for i in range(len(parts[0]))]
    bottom = [parts[2][i] + parts[3][i] for i in range(len(parts[2]))]
    return top + bottom

def op5(a):
    p = split(a)
    return merge([p[2], p[0], p[3], p[1]])

def op6(a):
    p = split(a)
    return merge([p[1], p[3], p[0], p[2]])

funcs = {1: op1, 2: op2, 3: op3, 4: op4, 5: op5, 6: op6}
for op in ops:
    arr = funcs[op](arr)
print('\n'.join(' '.join(map(str, row)) for row in arr))

